// Shared application types.
// Import with: import type { User, CreateUserInput } from "@/types"

import type { useTranslations } from "next-intl"
import type { ClanDto } from "@/dtos/clanDTO"
import type { ClanMemberDto, PlayerClanDto } from "@/dtos/clanMemberDTO"
import type { ClanPostDto } from "@/dtos/clanPostDTO"
import type { ServerDto } from "@/dtos/serverDTO"
import type { PublicUserDto } from "@/dtos/userDTO"
import type {
  Clan as PrismaClan,
  ClanMember as PrismaClanMember,
  ClanPost as PrismaClanPost,
  ClanRole as PrismaClanRole,
  Region as PrismaRegion,
  Server as PrismaServer,
  User as PrismaUser,
  UserRole as PrismaUserRole,
} from "@prisma/client"

// ---------------------------------------------------------------------------
// User
// ---------------------------------------------------------------------------

/** User record as stored in the database (generated by Prisma). */
export type User = PrismaUser

/** Site-wide role: MEMBER (default), MOD or ADMIN. */
export type UserRole = PrismaUserRole

/**
 * Payload for creating a user. `fullname` is derived from name + surname.
 * `password` is the plain password, it is hashed before saving.
 * Steam fields are optional.
 */
export type CreateUserInput = Pick<User, "username" | "name" | "surname" | "email" | "password"> &
  Partial<Pick<User, "steamId" | "steamUsername" | "avatar">>

/** Payload for updating a user. All fields are optional. */
export type UpdateUserInput = Partial<CreateUserInput>

/** One page of the player list (getPlayers). */
export type PlayerList = {
  players: PublicUserDto[]
  // Number of players matching the filters, on all pages.
  total: number
  pageCount: number
}

// ---------------------------------------------------------------------------
// Clan
// ---------------------------------------------------------------------------

/** Clan record as stored in the database (generated by Prisma). */
export type Clan = PrismaClan

/** ROB RUN server region. */
export type Region = PrismaRegion

/** One page of the clan list (getClans). */
export type ClanList = {
  clans: ClanDto[]
  // Number of clans matching the filters, on all pages.
  total: number
  pageCount: number
}

/** Payload for creating a clan. */
export type CreateClanInput = Pick<Clan, "clanName" | "clanTag" | "clanHref" | "region">

/** Payload for updating a clan. All fields are optional. */
export type UpdateClanInput = Partial<CreateClanInput>

// ---------------------------------------------------------------------------
// Clan member
// ---------------------------------------------------------------------------

/** Rank of a user inside a clan (ROB RUN ranks: LEADER > OFFICER > FIGHTER > RECRUIT). */
export type ClanRole = PrismaClanRole

/** Membership record linking a user to a clan (generated by Prisma). */
export type ClanMember = PrismaClanMember

/** A clan with its active servers and members, highest rank first (getClan). */
export type ClanDetail = {
  clan: ClanDto
  servers: ServerDto[]
  // True for the leader and officers of the clan.
  canManage: boolean
  members: ClanMemberDto[]
}

/** Results of the main menu search bar (search). */
export type SearchResults = {
  clans: ClanDto[]
  players: PublicUserDto[]
}

/** Clan post record as stored in the database (generated by Prisma). */
export type ClanPost = PrismaClanPost

/** One page of the wall of a clan (getClanPosts). */
export type ClanPostList = {
  posts: ClanPostDto[]
  // Number of posts on all pages.
  total: number
  pageCount: number
}

/** A player with their clans and active servers (getPlayer). */
export type PlayerDetail = {
  player: PublicUserDto
  clans: PlayerClanDto[]
  servers: ServerDto[]
}

/** Payload for adding a user to a clan. `role` defaults to RECRUIT. */
export type CreateClanMemberInput = Pick<ClanMember, "userId" | "clanId"> &
  Partial<Pick<ClanMember, "role">>

/** Payload for updating a membership. Only the role can change. */
export type UpdateClanMemberInput = Pick<ClanMember, "role">

// ---------------------------------------------------------------------------
// Server
// ---------------------------------------------------------------------------

/** Game server record as stored in the database (generated by Prisma). */
export type Server = PrismaServer

/** Payload for creating a server. */
export type CreateServerInput = Pick<Server, "serverName" | "beganAt">

/** Payload for updating a server. All fields are optional. */
export type UpdateServerInput = Partial<CreateServerInput>

// ---------------------------------------------------------------------------
// Auth
// ---------------------------------------------------------------------------

/** The logged-in user resolved from an access token. */
export type AccessTokenPayload = {
  userId: string
  username: string
}

// ---------------------------------------------------------------------------
// API
// ---------------------------------------------------------------------------

/**
 * Result of a server action. On failure `error` is a translated message for
 * the whole form and `fieldErrors` holds translated messages per field.
 */
export type ActionResult<T = undefined> =
  | { success: true, data: T }
  | { success: false, error?: string, fieldErrors?: Record<string, string> }

/** Standard response envelope for API routes. */
export type ApiResponse<T> =
  | { success: true, data: T }
  | { success: false, error: string }

// ---------------------------------------------------------------------------
// i18n
// ---------------------------------------------------------------------------

// Makes next-intl type-safe: locales and translation keys are checked at
// compile time against i18n/config.ts and messages/en.json.
declare module "next-intl" {
  interface AppConfig {
    Locale: (typeof import("./i18n/config"))["locales"][number]
    Messages: typeof import("./messages/en.json")
  }
}

/**
 * Translator for the "Validation" namespace. Zod schemas are built by factory
 * functions that take this, so validation messages follow the active language:
 * `useTranslations("Validation")` on the client, `getTranslations("Validation")`
 * on the server.
 */
export type ValidationTranslator = ReturnType<typeof useTranslations<"Validation">>
